#include <stdio.h>
#include <string.h>
#define MOD 1000000007

int main() {
    char s[200005];
    scanf("%s", s);
    int n = strlen(s);

    int dp[13] = {0};
    int ndp[13];

    // Initial: before any digits, remainder is 0
    dp[0] = 1;

    for (int i = 0; i < n; i++) {
        memset(ndp, 0, sizeof(ndp));
        if (s[i] == '?') {
            for (int d = 0; d <= 9; d++) {
                for (int r = 0; r < 13; r++) {
                    int nr = (r * 10 + d) % 13;
                    ndp[nr] = (ndp[nr] + dp[r]) % MOD;
                }
            }
        } else {
            int d = s[i] - '0';
            for (int r = 0; r < 13; r++) {
                int nr = (r * 10 + d) % 13;
                ndp[nr] = (ndp[nr] + dp[r]) % MOD;
            }
        }
        memcpy(dp, ndp, sizeof(dp));
    }

    printf("%d\n", dp[5]);
    return 0;
}

#include <stdio.h>
