#define MOD 1000000007

int main() {
    char s[100005];
    scanf("%s", s);
    int n = strlen(s);

    long long dp[2][13];
    memset(dp[0], 0, sizeof(dp[0]));
    dp[0][0] = 1;

    int cur = 0, nxt = 1;

    for (int i = 0; i < n; i++) {
        memset(dp[nxt], 0, sizeof(dp[nxt]));

        if (s[i] == '?') {
            // Try all digits 0-9
            for (int r = 0; r < 13; r++) {
                if (dp[cur][r] == 0) continue;
                for (int d = 0; d <= 9; d++) {
                    int nr = (r * 10 + d) % 13;
                    dp[nxt][nr] = (dp[nxt][nr] + dp[cur][r]) % MOD;
                }
            }
        } else {
            int d = s[i] - '0';
            for (int r = 0; r < 13; r++) {
                if (dp[cur][r] == 0) continue;
                int nr = (r * 10 + d) % 13;
                dp[nxt][nr] = (dp[nxt][nr] + dp[cur][r]) % MOD;
            }
        }

        cur = 1 - cur;
        nxt = 1 - nxt;
    }

    printf("%lld\n", dp[cur][5]);

    return 0;
}

