#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    cin >> S;

    vector<long long> dp(13, 0), ndp(13, 0);
    dp[0] = 1;

    for (char c : S) {
        fill(ndp.begin(), ndp.end(), 0);

        if (c == '?') {
            for (int r = 0; r < 13; ++r) {
                if (dp[r] == 0) continue;
                for (int d = 0; d <= 9; ++d) {
                    int nr = (r * 10 + d) % 13;
                    ndp[nr] += dp[r];
                    if (ndp[nr] >= MOD) ndp[nr] -= MOD;
                }
            }
        } else {
            int d = c - '0';
            for (int r = 0; r < 13; ++r) {
                if (dp[r] == 0) continue;
                int nr = (r * 10 + d) % 13;
                ndp[nr] += dp[r];
                if (ndp[nr] >= MOD) ndp[nr] -= MOD;
            }
        }

        dp.swap(ndp);
    }

    cout << dp[5] % MOD << '\n';
    return 0;
}

