                if (dp[i][r] == 0) continue;
                if (c == '?') {
                    for (int d = 0; d <= 9; d++) {
                        int newR = (r * 10 + d) % 13;
                        dp[i + 1][newR] = (dp[i + 1][newR] + dp[i][r]) % MOD;
                    }
                } else {
                    int d = c - '0';
                    int newR = (r * 10 + d) % 13;
                    dp[i + 1][newR] = (dp[i + 1][newR] + dp[i][r]) % MOD;
                }
            }
        }

        System.out.println(dp[n][5]);
        sc.close();
    }
