from collections import defaultdict

def solve():
    MOD = 10**9 + 7
    S = input().strip()

    dp = defaultdict(int)
    dp[0] = 1

    for ch in S:
        new_dp = defaultdict(int)
        if ch == '?':
            digits = range(10)
        else:
            digits = [int(ch)]

        for r, cnt in dp.items():
            for d in digits:
                new_r = (r * 10 + d) % 13
                new_dp[new_r] = (new_dp[new_r] + cnt) % MOD

        dp = new_dp

    print(dp[5] % MOD)

